/**
 * Hrefs for the routes the App Router actually serves.
 *
 * Alerts, search hits and digest entries must all use these. A link built from
 * an id alone (`/issues/:id`, `/settings/members`) does not match any page.
 */
import { issuePath, projectPath, settingsPath } from "@/lib/url";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import type { CommentId, IssueId, OrgId, ProjectId } from "@/types/common";

/** Issue page: `/{org}/projects/{project}/issues/{number}`. */
export async function issuePageHref(
  orgId: OrgId,
  issueId: IssueId,
): Promise<string> {
  const org = await orgRepo.findOrgById(orgId);
  const issue = await issueRepo.findIssueById(orgId, issueId);
  if (!org || !issue) return `/issues/${issueId}`;

  const project = await projectRepo.findProjectById(orgId, issue.projectId);
  if (!project) return `/issues/${issueId}`;

  return issuePath(org.slug, project.slug, issue.number);
}

/** Project page: `/{org}/projects/{project}`. */
export async function projectPageHref(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<string> {
  const org = await orgRepo.findOrgById(orgId);
  const project = await projectRepo.findProjectById(orgId, projectId);
  if (!org || !project) return `/projects/${projectId}`;

  return projectPath(org.slug, project.slug);
}

/**
 * A comment lives on its issue page. Search hits for comments open that
 * issue, not a standalone comment route (there isn't one).
 */
export async function commentPageHref(
  orgId: OrgId,
  commentId: CommentId,
): Promise<string> {
  const comment = await commentRepo.findCommentById(orgId, commentId);
  if (!comment) return `/comments/${commentId}`;
  return issuePageHref(orgId, comment.issueId);
}

/** Settings section: `/{org}/settings/{section}`. */
export async function settingsSectionHref(
  orgId: OrgId,
  section: string,
): Promise<string> {
  const org = await orgRepo.findOrgById(orgId);
  if (!org) return `/settings/${section}`;
  return settingsPath(org.slug, section);
}

