export async function markRead(
  actor: Actor,
  input: MarkNotificationReadInput,
): Promise<Notification> {
  assertOrgScope(actor, input.orgId);

  const existing = await notificationRepo.findNotificationById(
    input.orgId,
    input.notificationId,
  );
  if (!existing) {
    throw new Error(`Notification ${input.notificationId} not found`);
  }

  // The row's recipient, not the caller's own id: passing your own id to
  // `can()` must not let you mark someone else's alert.
  assertCan(
    actor,
    "notification:manage",
    notificationResource(input.orgId, existing.recipientId),
  );
  return notificationRepo.markRead(
    input.orgId,
    input.notificationId,
    toIsoTimestamp(new Date()),
  );
}

