/** Stable title so two refusals of the same resource collapse while unread. */
function planLimitTitle(resource: LimitedResource): string {
  return `Plan limit reached: ${resource}`;
}

/** Members with the owner role; the org record's owner if that list is empty. */
async function workspaceOwnerIds(orgId: OrgId): Promise<readonly UserId[]> {
  const page = await memberRepo.listMembers({
    orgId,
    role: "owner",
    limit: 100,
    cursor: null,
  });
  const ids = page.items.map((member) => member.userId);
  if (ids.length > 0) return ids;

  const org = await orgRepo.findOrgById(orgId);
  return org ? [org.ownerId] : [];
}

/**
 * Tells each workspace owner that a write was refused for `resource`.
 * While that owner's alert is still unread, another refusal of the same
 * resource adds nothing. A different resource is a separate alert. The owner
 * is told even when they are the one who tried.
 */
export async function notifyPlanLimitReached(
  orgId: OrgId,
  resource: LimitedResource,
): Promise<void> {
  if (!PLAN_LIMIT_RESOURCES.has(resource)) return;

  const org = await orgRepo.findOrgById(orgId);
  if (!org) return;

  const title = planLimitTitle(resource);
  const owners = await workspaceOwnerIds(orgId);
  const pending: UserId[] = [];

  for (const ownerId of owners) {
    const already = await notificationRepo.hasUnreadNotification(
      orgId,
      ownerId,
      "plan_limit_reached",
      title,
    );
    if (!already) pending.push(ownerId);
  }

  await notify(orgId, "plan_limit_reached", pending, {
    title,
    body: `The ${resource} limit on the ${org.plan} plan has been reached.`,
    href: await settingsSectionHref(orgId, "billing"),
    actorId: null,
  });
}

async function deliverIssueAlert(
  orgId: OrgId,
  issueId: IssueId,
  kind: NotificationKind,
  recipients: readonly UserId[],
  title: string,
  body: string,
  actorId: UserId | null,
): Promise<void> {
  if (recipients.length === 0) return;
  const present = recipients.filter((id): id is UserId => id !== null);
  if (present.length === 0) return;

  await notify(orgId, kind, present, {
    title,
    body,
    href: await issuePageHref(orgId, issueId),
    actorId,
  });
}

