  // the same way as a later assign, unless they created the issue themselves
  // (`notify` skips the actor).
  subscribe("issue.created", async (payload) => {
    if (payload.assigneeId === null) return;
    await deliverIssueAlert(
      payload.orgId,
      payload.issueId,
      "issue_assigned",
310→      [payload.assigneeId],
      "You were assigned an issue",
      `Issue ${payload.issueId} is now yours`,
      payload.actorId,
    );
  });

  subscribe("issue.status_changed", async (payload) => {
    const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
    if (!issue?.assigneeId) return;
320→    await deliverIssueAlert(
      payload.orgId,
      payload.issueId,
      "issue_status_changed",
      [issue.assigneeId],
      "Issue status changed",
      `Issue ${payload.issueId} moved from ${payload.from} to ${payload.to}`,
      payload.actorId,
    );
  });
330→
  subscribe("issue.overdue", async (payload) => {
    if (payload.assigneeId === null) return;
    await deliverIssueAlert(
      payload.orgId,
      payload.issueId,
      "issue_overdue",
      [payload.assigneeId],
      "An issue is overdue",
      `Issue ${payload.issueId} was due ${payload.dueAt}`,
340→      null,
    );
  });

  subscribe("comment.created", async (payload) => {
    const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
    const watchers = issue
      ? [issue.authorId, ...(issue.assigneeId ? [issue.assigneeId] : [])]
      : [];
    const href = await issuePageHref(payload.orgId, payload.issueId);
350→
    await notify(payload.orgId, "comment_created", watchers, {
      title: "New comment",
      body: `A comment was added to issue ${payload.issueId}`,
      href,
      actorId: payload.actorId,
    });

    if (payload.mentionedUserIds.length > 0) {
      await notify(
360→        payload.orgId,
        "comment_mention",
        payload.mentionedUserIds,
        {
          title: "You were mentioned",
          body: `You were mentioned on issue ${payload.issueId}`,
          href,
          actorId: payload.actorId,
        },
      );
370→    }
  });

  // The workspace owner is told. The person who joined is not told about
  // themselves, including when they are the owner (actorId is the joiner).
  subscribe("member.joined", async (payload) => {
    const org = requireFound(
      await orgRepo.findOrgById(payload.orgId),
      "Organization",
      payload.orgId,
380→    );
    const owners = await workspaceOwnerIds(payload.orgId);
    await notify(payload.orgId, "member_joined", owners, {
      title: "A new member joined",
      body: `${payload.userId} joined ${org.name} as ${payload.role}`,
      href: await settingsSectionHref(payload.orgId, "members"),
      actorId: payload.userId,
    });
  });
}
390→
registerFanOut();
