import { toIsoTimestamp } from "@/types/common";
import { issuePageHref, settingsSectionHref } from "./app-links";
import { notificationResource, requireFound } from "./_support";
import type {
  ListNotificationsInput,
  MarkNotificationReadInput,
  UpdateNotificationPreferenceInput,
} from "@/schemas/notification";
import type { LimitedResource } from "@/types/billing";
import type { IssueId, OrgId, Page, UserId } from "@/types/common";
import type { FlagContext } from "@/types/feature-flag";
import type { Actor } from "@/types/member";
import type {
  Notification,
  NotificationChannel,
  NotificationKind,
  NotificationPreference,
} from "@/types/notification";

export type NotificationPayload = {
  title: string;
  body: string;
  href: string;
  actorId: UserId | null;
};

/** Channels used when a recipient has never touched their preferences. */
const DEFAULT_CHANNELS: readonly NotificationChannel[] = ["in_app", "email"];

/**
 * Quota refusals that tell the workspace owner. The periodic usage recount
 * is not one of these — it refuses nothing, so it must not call
 * `notifyPlanLimitReached`.
 */
const PLAN_LIMIT_RESOURCES: ReadonlySet<LimitedResource> = new Set([
  "seats",
  "projects",
  "issuesPerProject",
  "storageMb",
  "webhooks",
]);

/**
 * Writes one notification row per recipient, each with the channel set that
 * recipient's preferences allow. A recipient who has muted every channel is
 * skipped entirely rather than given a row nobody will ever see.
 */
export async function notify(
  orgId: OrgId,
  kind: NotificationKind,
  recipients: readonly UserId[],
  payload: NotificationPayload,
): Promise<readonly Notification[]> {
  if (recipients.length === 0) return [];

  const org = await orgRepo.findOrgById(orgId);
  const flags: FlagContext = {
    orgId,
    userId: payload.actorId,
    plan: org?.plan ?? "free",
    role: null,
    overrides: org?.settings.enabledFlagOverrides,
  };

  const rows = [];

  for (const recipientId of new Set(recipients)) {
    if (recipientId === payload.actorId) continue;

    const preference = await preferenceRepo.getPreference(
      orgId,
      recipientId,
      kind,
    );
    const channels = resolveChannels(preference, flags);
    if (channels.length === 0) continue;

    rows.push({
      orgId,
      recipientId,
      kind,
      title: payload.title,
      body: payload.body,
      href: payload.href,
      actorId: payload.actorId,
      channels,
    });
  }

  return notificationRepo.insertNotifications(orgId, rows);
}

export async function listNotifications(
  actor: Actor,
  input: ListNotificationsInput,
): Promise<Page<Notification>> {
  assertOrgScope(actor, input.orgId);
  assertCan(
    actor,
    "notification:read",
    notificationResource(input.orgId, input.recipientId),
  );
  return notificationRepo.listNotifications(input);
}

export async function markRead(
  actor: Actor,
  input: MarkNotificationReadInput,
): Promise<Notification> {
  assertOrgScope(actor, input.orgId);

  const existing = await notificationRepo.findNotificationById(
    input.orgId,
    input.notificationId,
  );
  if (!existing) {
    throw new Error(`Notification ${input.notificationId} not found`);
  }

  // The row's recipient, not the caller's own id: passing your own id to
  // `can()` must not let you mark someone else's alert.
  assertCan(
    actor,
    "notification:manage",
    notificationResource(input.orgId, existing.recipientId),
  );
  return notificationRepo.markRead(
    input.orgId,
    input.notificationId,
    toIsoTimestamp(new Date()),
  );
}

export async function markAllRead(
  actor: Actor,
  orgId: OrgId,
): Promise<number> {
  assertOrgScope(actor, orgId);
  assertCan(
    actor,
    "notification:manage",
    notificationResource(orgId, actor.userId),
  );
  return notificationRepo.markAllRead(
    orgId,
    actor.userId,
    toIsoTimestamp(new Date()),
  );
}

export async function updatePreference(
  actor: Actor,
  input: UpdateNotificationPreferenceInput,
): Promise<NotificationPreference> {
  assertOrgScope(actor, input.orgId);
  assertCan(
    actor,
    "notification:manage",
    notificationResource(input.orgId, input.userId),
  );
  return preferenceRepo.upsertPreference(input);
}

/**
 * Turns a stored preference into the channels one notification will use.
 * `digestOnly` suppresses the immediate email but keeps the in-app row, and
 * the email channel additionally requires the org's `digest_email` plan flag.
 */
export function resolveChannels(
  preference: NotificationPreference | null,
  flags: FlagContext,
): readonly NotificationChannel[] {
  if (preference === null) return DEFAULT_CHANNELS;

  const channels: NotificationChannel[] = [];
  if (preference.inApp) channels.push("in_app");

  const emailAllowed =
    preference.email &&
    (!preference.digestOnly || isEnabled("digest_email", flags));

  if (emailAllowed) channels.push("email");
  return channels;
}

/** Stable title so two refusals of the same resource collapse while unread. */
function planLimitTitle(resource: LimitedResource): string {
  return `Plan limit reached: ${resource}`;
}

/** Members with the owner role; the org record's owner if that list is empty. */
async function workspaceOwnerIds(orgId: OrgId): Promise<readonly UserId[]> {
  const page = await memberRepo.listMembers({
    orgId,
    role: "owner",
    limit: 100,
    cursor: null,
  });
  const ids = page.items.map((member) => member.userId);
  if (ids.length > 0) return ids;

  const org = await orgRepo.findOrgById(orgId);
  return org ? [org.ownerId] : [];
}

/**
 * Tells each workspace owner that a write was refused for `resource`.
 * While that owner's alert is still unread, another refusal of the same
 * resource adds nothing. A different resource is a separate alert. The owner
 * is told even when they are the one who tried.
 */
export async function notifyPlanLimitReached(
  orgId: OrgId,
  resource: LimitedResource,
): Promise<void> {
  if (!PLAN_LIMIT_RESOURCES.has(resource)) return;

  const org = await orgRepo.findOrgById(orgId);
  if (!org) return;

  const title = planLimitTitle(resource);
  const owners = await workspaceOwnerIds(orgId);
  const pending: UserId[] = [];

  for (const ownerId of owners) {
    const already = await notificationRepo.hasUnreadNotification(
      orgId,
      ownerId,
      "plan_limit_reached",
      title,
    );
    if (!already) pending.push(ownerId);
  }

  await notify(orgId, "plan_limit_reached", pending, {
    title,
    body: `The ${resource} limit on the ${org.plan} plan has been reached.`,
    href: await settingsSectionHref(orgId, "billing"),
    actorId: null,
  });
}

async function deliverIssueAlert(
  orgId: OrgId,
  issueId: IssueId,
  kind: NotificationKind,
  recipients: readonly UserId[],
  title: string,
  body: string,
  actorId: UserId | null,
): Promise<void> {
  if (recipients.length === 0) return;
  const present = recipients.filter((id): id is UserId => id !== null);
  if (present.length === 0) return;

  await notify(orgId, kind, present, {
    title,
    body,
    href: await issuePageHref(orgId, issueId),
    actorId,
  });
}

