import { emit } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as notificationRepo from "@/server/repositories/notification-repository";
import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as attachmentService from "@/server/services/attachment-service";
import { buildDigest } from "@/server/services/digest-service";
import * as invitationService from "@/server/services/invitation-service";
import * as issueService from "@/server/services/issue-service";
import {
  listNotifications,
  markAllRead,
  markRead,
  updatePreference,
} from "@/server/services/notification-service";
import * as projectService from "@/server/services/project-service";
import { indexComment, indexIssue, indexProject, search } from "@/server/services/search-service";
import * as usageService from "@/server/services/usage-service";
import * as webhookService from "@/server/services/webhook-service";
import { toIsoTimestamp } from "@/types/common";
import type { CommentId, IssueId, UserId } from "@/types/common";
import {
  createTenant,
  issueInput,
  useTemporaryDatabase,
} from "./tests/server/_support/fixtures";

function assert(cond: unknown, message: string): asserts cond {
  if (!cond) throw new Error(message);
}

async function main(): Promise<void> {
  const cleanup = await useTemporaryDatabase();
  try {
    const tenant = await createTenant("links", "growth");
    const free = await createTenant("full", "free");
    const orgId = tenant.org.id;
    const owner = tenant.actors.owner;
    const member = tenant.actors.member;
    const admin = tenant.actors.admin;

    const assigned = await issueService.createIssue(
